'use strict';
// Read-only public data channel. No credentials, arbitrary URLs or executable content.
const publicDataBase='https://raw.githubusercontent.com/bensonlee5/enso-atlas/main/dist/data/';
const publicDataFiles=['cfs-weekly-raw-60days.json','cfs-weekly-anomalies.json','enso-observations.json','ensemble-percentiles.json','verification.json','cfs-global-60days.json','aifs-global-snapshots.json'];
const publicDataCache='enso-atlas-public-noaa-v3';let publicDataBusy=false;
function requireData(ok,message){if(!ok)throw Error(message)}
function goodDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}/.test(s)&&Number.isFinite(Date.parse(s))}
function numericArray(a,n,nullable=false){return Array.isArray(a)&&a.length===n&&a.every(x=>Number.isFinite(x)||(nullable&&x===null))}
function validatePublicProducts(p){const raw=p[publicDataFiles[0]],a=p[publicDataFiles[1]],e=p[publicDataFiles[2]],q=p[publicDataFiles[3]];
 for(const product of [raw,a,q]){requireData(Array.isArray(product.gridCoordinates)&&product.gridCoordinates.length>0&&product.gridCoordinates.length<10000,'Invalid grid');requireData(product.gridCoordinates.every(c=>Array.isArray(c)&&c.length===2&&c.every(Number.isFinite)&&Math.abs(c[0])<=90&&Math.abs(c[1])<=180),'Invalid coordinates')}
 requireData(goodDate(raw.run)&&goodDate(q.run)&&goodDate(a.initialDate),'Invalid initialization');
 requireData(Array.isArray(raw.weeks)&&raw.weeks.length===8,'Raw weeks');for(const w of raw.weeks){requireData(goodDate(w.intervalStart)&&goodDate(w.intervalEndExclusive),'Raw dates');for(const field of ['temperature','precipitationRate'])requireData(numericArray(w[field],raw.gridCoordinates.length),'Raw values')}
 for(const field of ['tmpsfc','prec']){const x=a.fields[field];requireData(x?.frames?.length===4,'Anomaly weeks');for(const f of x.frames)requireData(goodDate(f.startDate)&&goodDate(f.endDate)&&numericArray(f.values,a.gridCoordinates.length,true),'Anomaly data')}
 requireData(q.memberCount===4&&q.memberIDs?.join(',')==='01,02,03,04'&&q.weeks?.length===8&&q.remainingDays57to60,'Ensemble structure');
 for(const w of [...q.weeks,q.remainingDays57to60]){requireData(goodDate(w.intervalStart)&&goodDate(w.intervalEndExclusive),'Ensemble dates');for(const f of ['temperature','precipitationRate']){const keys=['p1','p5','p10','p50','p90','p95','p99'];for(const key of keys)requireData(numericArray(w[f][key],q.gridCoordinates.length),'Complete seven-quantile values required');requireData(keys.slice(1).every((key,j)=>w[f][key].every((v,i)=>w[f][keys[j]][i]<=v)),'Unordered quantiles')}}
 requireData(Array.isArray(e.observations)&&e.observations.length>0&&e.observations.length<=200,'ENSO rows');for(const o of e.observations)requireData(goodDate(o.date)&&Number.isFinite(o.nino34?.anomaly),'ENSO values');
 const sources=[...(raw.sources||[]),...(q.sources||[]),a.fields.prec.source,a.fields.tmpsfc.source,e.source];for(const source of sources){const u=new URL(source);requireData(u.protocol==='https:'&&['nomads.ncep.noaa.gov','www.cpc.ncep.noaa.gov'].includes(u.hostname),'Unapproved source URL')}
 requireData(Date.now()-Date.parse(raw.run)<14*86400000&&Date.now()-Date.parse(q.run)<14*86400000,'Repository model data too old');const v=p['verification.json'];requireData(v?.schemaVersion===1&&goodDate(v.generatedAt)&&v.counts&&v.temperature,'Invalid verification report');for(const k of ['verified','pending'])requireData(Number.isInteger(v.counts[k])&&v.counts[k]>=0,'Invalid verification counts');for(const group of ['byLead','byLocation']){requireData(Array.isArray(v.temperature[group]),'Invalid verification group');for(const row of v.temperature[group])for(const key of ['bias','mae','rmse'])requireData(row[key]===null||Number.isFinite(row[key]),'Invalid verification score')}const gc=p['cfs-global-60days.json'],ga=p['aifs-global-snapshots.json'];for(const g of [gc,ga]){requireData(goodDate(g.run)&&g.gridCoordinates?.length>1000&&g.gridCoordinates.length<10000,'Invalid global grid/run');requireData(g.gridCoordinates.every(c=>c.length===2&&c.every(Number.isFinite)&&Math.abs(c[0])<=90&&Math.abs(c[1])<=180),'Global coordinates')}requireData(gc.days?.length===60&&ga.frames?.length===8,'Global horizon');for(const f of gc.days){requireData(goodDate(f.date),'Global date');for(const key of ['temperatureC','precipitationMmDay'])requireData(numericArray(f[key],gc.gridCoordinates.length),'Global field')}if(gc.comparisonSnapshots)for(const f of gc.comparisonSnapshots)requireData(goodDate(f.validTime)&&numericArray(f.temperatureC,gc.gridCoordinates.length)&&f.statistic==='instantaneous 2m air temperature','Invalid matched snapshot');for(const f of ga.frames)requireData(['2t','tp'].includes(f.metadata?.shortName)&&numericArray(f.values,ga.gridCoordinates.length),'AIFS field');for(const source of [...(gc.sources||[]),ga.source]){const u=new URL(source);requireData(u.protocol==='https:'&&['nomads.ncep.noaa.gov','data.ecmwf.int'].includes(u.hostname),'Unapproved global source')}requireData(Date.now()-Date.parse(ga.run)<14*86400000&&Date.now()-Date.parse(gc.run)<14*86400000,'Global forecast stale');return p;
}
async function verifyPublicBundle(bundle){const m=bundle.manifest;requireData(m?.schemaVersion===1&&goodDate(m.generatedAt),'Invalid manifest');requireData(Object.keys(m.files||{}).sort().join('|')===publicDataFiles.slice().sort().join('|'),'Unexpected manifest files');const p={};for(const name of publicDataFiles){const text=bundle.texts[name],meta=m.files[name];requireData(typeof text==='string'&&meta.bytes>0&&meta.bytes<5000000&&/^[a-f0-9]{64}$/.test(meta.sha256),'Invalid file metadata');const bytes=new TextEncoder().encode(text);requireData(bytes.length===meta.bytes,'Byte count mismatch');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');requireData(hash===meta.sha256,'Hash mismatch');p[name]=JSON.parse(text)}return validatePublicProducts(p)}
function applyPublicData(p,manifest,checkedAt){const locations=cfs?.sampledLocations;const oldWeek=longWeek;cfs=p[publicDataFiles[0]];if(locations)cfs.sampledLocations=locations;anomalies=p[publicDataFiles[1]];ensoLatest=p[publicDataFiles[2]].observations.at(-1);ensemble=p[publicDataFiles[3]];longWeek=oldWeek;setupWeeks();feedDescription='Hash-verified repository data · generated '+manifest.generatedAt.slice(0,16).replace('T',' ')+' UTC · checked '+checkedAt.slice(0,16).replace('T',' ')+' UTC';$('feedStatus').textContent=feedDescription;renderEnso();if(longMode)renderLong();if(typeof globalAssets!=='undefined'){globalAssets.cfs=p['cfs-global-60days.json'];globalAssets.aifs=p['aifs-global-snapshots.json'];if(globalMode)renderGlobal()}if(typeof verificationReport!=='undefined'){verificationReport=p['verification.json'];renderVerification()}}
async function refreshPublicData(force=false){if(publicDataBusy)return;publicDataBusy=true;try{await Promise.all([initialLoad,ensembleLoad]);requireData(crypto?.subtle,'Secure hash validation unavailable');let cached=null;try{cached=JSON.parse(localStorage.getItem(publicDataCache))}catch{}if(cached){try{const p=await verifyPublicBundle(cached);applyPublicData(p,cached.manifest,cached.checkedAt);if(!force&&Date.now()-Date.parse(cached.checkedAt)<3600000)return}catch{}}
 const bucket=Math.floor(Date.now()/3600000),r=await fetch(publicDataBase+'refresh-manifest.json?v='+bucket,{cache:'no-cache',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Manifest not available');const manifest=await r.json();requireData(manifest?.files,'Missing file list');const texts={};for(const name of publicDataFiles){requireData(manifest.files[name]?.sha256,'Missing file hash');const response=await fetch(publicDataBase+name+'?v='+manifest.files[name].sha256,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('Data unavailable');texts[name]=await response.text()}
 const bundle={manifest,texts,checkedAt:new Date().toISOString()},p=await verifyPublicBundle(bundle);applyPublicData(p,manifest,bundle.checkedAt);try{localStorage.setItem(publicDataCache,JSON.stringify(bundle))}catch{}
 }catch{const el=$('feedStatus');if(el)el.textContent='Repository refresh unavailable or failed validation. Keeping the previous source data; check each product’s run date.'}finally{publicDataBusy=false;if(typeof syncExplorerState==='function')syncExplorerState()}}
refreshPublicData();setInterval(()=>{if(document.visibilityState==='visible')refreshPublicData()},3600000);
